using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
namespace OcctSharp.Generator.Tests;
public sealed class LocalFeatureAdapterContractTests {
 static ClosedWorkflowOperationContract Contract=>ClosedWorkflowOperationContract.LocalFeatureAdapters;
 static BindingDeclaration Row(CopiedCollectionOperationContract.Operation op){string owner=op.NativeName.Split("::")[0];return new(op.StableId,op.NativeName,op.NativeName.EndsWith("::"+owner,StringComparison.Ordinal)?BindingDeclarationKind.Constructor:BindingDeclarationKind.Method,owner+".hxx",1,1){NativeSignature=op.Signature,Access=BindingAccess.Public,SupportState=op.Supporting&&op.NativeName!="BRepBuilderAPI_MakeShape::Shape"?BindingSupportState.Manual:BindingSupportState.Pending};}
 [Fact] public void ExactClosureRejectsSignatureAccessAndUnsafeDrift(){foreach(var op in Contract.Operations.Values){var row=Row(op);Assert.True(Contract.Contains(row));Assert.False(Contract.Contains(row with{NativeSignature=row.NativeSignature+" "}));Assert.False(Contract.Contains(row with{IsTemplated=true}));Assert.False(Contract.Contains(row with{Access=BindingAccess.Private}));if(!op.Supporting)Assert.False(Contract.Contains(row with{SupportState=BindingSupportState.Manual}));}Assert.Throws<InvalidDataException>(()=>ClosedWorkflowOperationEmitter.Emit("8.0.1",new([Row(Contract.Operations.Values.First(o=>!o.Supporting))]),Contract));}
 [Fact] public void NativeHeaderIsDeterministicAndPreservesPrivateOwnershipWithoutManualCredit(){var rows=Contract.Operations.Values.Select(Row).ToArray();var a=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows),Contract);var b=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows.Reverse()),Contract);Assert.Single(a.Files);Assert.Equal(a.Files[0].Content,b.Files[0].Content);Assert.Equal(112,a.SourceStableIds.Count);foreach(var manual in rows.Where(d=>d.SupportState==BindingSupportState.Manual)){Assert.DoesNotContain(manual.StableId,a.SourceStableIds);Assert.Contains("// Source: "+manual.StableId,a.Files[0].Content);}Assert.Contains("source.Size()>1000000",a.Files[0].Content);Assert.Contains("NCollection_List<TopoDS_Shape> Modified",a.Files[0].Content);Assert.Contains("operator=(const",a.Files[0].Content);Assert.DoesNotContain("void SetRadius(const occ::handle<Law_Function>",a.Files[0].Content);Assert.DoesNotContain("OCCTSHARP_CALL",a.Files[0].Content);}
 [Fact] public void SupportingSignaturesAloneCannotPublishAdapters(){var output=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(Contract.Operations.Values.Where(o=>o.Supporting).Select(Row)),Contract);Assert.Empty(output.Files);Assert.Empty(output.SourceStableIds);}
}
